class Solution:
    def mincostTickets(self, days: list[int], costs: list[int]) -> int:
        durations = [1, 7, 30]
        def dfs(i: int) -> int:
            if i >= len(days):
                return 0
            best = 10**9
            for dur, cost in zip(durations, costs):
                j = i
                while j < len(days) and days[j] < days[i] + dur:
                    j += 1
                best = min(best, cost + dfs(j))
            return best
        return dfs(0)

