class Solution:
    def mincostTickets(self, days: list[int], costs: list[int]) -> int:
        from functools import lru_cache
        durations = [1, 7, 30]
        @lru_cache(None)
        def dp(i: int) -> int:
            if i >= len(days):
                return 0
            ans = 10**9
            for dur, cost in zip(durations, costs):
                j = i
                while j < len(days) and days[j] < days[i] + dur:
                    j += 1
                ans = min(ans, cost + dp(j))
            return ans
        return dp(0)

